anchors = [(11, 3, 3), (11, 14, 2)]

for ar, ac, val in anchors:
    for r in range(rows):
        # FLIPPED checkerboard: even (r+c) parity gets value
        if (r + ac) % 2 == 0:
            result[r][ac] = val

print('{"action": "submit", "grid": ' + str(result) + '}')
